# -*- coding: utf-8 -*-
# 10.5회 하프 모의고사 (오답 재출제, 숫자만 조금 바꾸기) 새 6–10번.
# 원래 문항 dict를 복사해 수치만 한 세트로 바꿈(설정·발문·풀이 흐름·함정 구조 그대로).
ITEMS = {
  6: dict(body=r"""\(0&lt;a&lt;6\)인 실수 \(a\)와 최고차항의 계수의 절댓값이 \(1\)이고 \(f(0)=0\)인 이차함수 \(f(x)\)가 다음 조건을 만족시킬 때, \(f(4)\)의 값이 될 수 있는 정수의 개수는?""",
          cond=[('가', r"\(\displaystyle\int_0^6|f(x)|\,dx=\int_0^a f(x)\,dx-\int_a^6 f(x)\,dx\)"),
                ('나', r"\(\displaystyle\left|\int_0^6 f(x)\,dx\right|\le3\int_{a-2}^{a} f(x)\,dx\)")],
          choices=['6', '7', '8', '9', '10'],
          ans=3,
          key='I37', src='2024년 수능특강 [24009-0150] · 9회 12번 숫자 변경',
          wrongs=['6', '10'],
          level='중',
          sol=r"(가)에서 \(\displaystyle\int_0^a\{|f(x)|-f(x)\}\,dx+\int_a^6\{|f(x)|+f(x)\}\,dx=0\)이고 두 피적분함수가 모두 \(0\) 이상이므로 닫힌구간 \([0,\ a]\)에서 \(f(x)\ge0\), 닫힌구간 \([a,\ 6]\)에서 \(f(x)\le0\)이다. 따라서 \(f(a)=0\)이다. \(f(0)=0\)이므로 \(f(x)=kx(x-a)\)이고, \(0&lt;x&lt;a\)에서 \(f(x)\ge0\)이려면 \(k&lt;0\)이므로 \(k=-1\), \(f(x)=-x(x-a)\)이다. 이 함수는 \([a,\ 6]\)에서 \(f(x)\le0\)도 만족시킨다.<br>곡선 \(y=f(x)\)는 직선 \(x=\dfrac a2\)에 대하여 대칭이고, 구간 \([a-2,\ a]\)는 이 직선에 대하여 구간 \([0,\ 2]\)와 대칭이므로<br>\(\displaystyle\int_{a-2}^{a}f(x)\,dx=\int_0^2 f(x)\,dx=\int_0^2(-x^2+ax)\,dx=2a-\dfrac83\)<br>이다. 또 \(\displaystyle\int_0^6 f(x)\,dx=\int_0^6(-x^2+ax)\,dx=18a-72\)이므로 (나)는 \(|18a-72|\le6a-8\)이다.<br>(i) \(18a-72\le6a-8\)에서 \(a\le\dfrac{16}3\)<br>(ii) \(-(18a-72)\le6a-8\)에서 \(a\ge\dfrac{10}3\)<br>따라서 \(\dfrac{10}3\le a\le\dfrac{16}3\)이다. \(f(4)=-4(4-a)=4a-16\)은 \(a\)의 값이 커지면 커지고, \(a\)가 이 범위에서 연속으로 움직이므로 \(f(4)\)의 값의 범위는 \(-\dfrac83\le f(4)\le\dfrac{16}3\)이다. 따라서 \(f(4)\)의 값이 될 수 있는 정수는 \(-2,\ -1,\ \cdots,\ 5\)의 \(8\)개이다.",
          fast=r"(가) ⇔ \([0,\ a]\)에서 \(f\ge0\), \([a,\ 6]\)에서 \(f\le0\) → \(f=-x(x-a)\). 축 \(x=\dfrac a2\) 대칭으로 \(\displaystyle\int_{a-2}^{a}f=\int_0^2f=2a-\dfrac83\), \(\displaystyle\int_0^6f=18(a-4)\). \(|18(a-4)|\le6a-8\) ⇔ \(\dfrac{10}3\le a\le\dfrac{16}3\)(아래 끝은 왼쪽 적분이 음수인 쪽 \(-X\le Y\), 위 끝은 \(X\le Y\)). \(f(4)=4a-16\in\left[-\dfrac83,\ \dfrac{16}3\right]\) → 정수 \(8\)개.",
          wrong=r"① \(6\): (나)를 '\(\displaystyle\int_0^6 f(x)\,dx\ge0\)'으로 읽어 아래 끝을 \(a=4\)로 잡은 값(\(4\le a\le\dfrac{16}3\), \(0\le f(4)\le\dfrac{16}3\); 왼쪽 적분이 음수인 \(\dfrac{10}3\le a&lt;4\)를 놓침) / ⑤ \(10\): \(-X\le Y\)의 \(a\ge\dfrac{10}3\)만 쓰고 \(X\le Y\)(위 끝 \(a\le\dfrac{16}3\))를 빼먹어 \(\dfrac{10}3\le a&lt;6\), \(-\dfrac83\le f(4)&lt;8\)로 센 값(9회에서 고른 ⑤와 같은 실수)",
          note=r"9회 12번(I37 변형)에서 수치만 바꿈: 범위 선언 \(0&lt;a&lt;3\) → \(0&lt;a&lt;6\), 계수의 절댓값 \(2\) → \(1\), (가)·(나)의 적분 끝 \(3\) → \(6\), (나)의 구간 \([a-1,\ a]\) → \([a-2,\ a]\)(바깥 계수 \(3\)은 그대로), 묻는 값 \(f(3)\) → \(f(4)\). 풀이 흐름(부호 구간 → \(f=-x(x-a)\) → 축 대칭으로 \([a-2,\ a]\) ↔ \([0,\ 2]\) → 왼쪽 적분의 부호가 \(a=4\)에서 바뀌어 절댓값 부등식의 두 쪽이 범위의 두 끝을 하나씩 정함 → 연속·증가 일차식의 정수 개수)과 두 함정(적분 \(\ge0\)으로 읽기, 위 끝 빼먹기) 그대로. 선지 \(6\)–\(10\) 공차 \(1\) 오름차순, 위 끝을 빼먹은 값이 원래처럼 ⑤에 옴."),
  7: dict(body=r"""상수 \(a\), \(b\)에 대하여 삼차함수 \(f(x)=x^3+ax^2+bx+2\)의 도함수 \(y=f'(x)\)의 그래프는 그림과 같이 \(x\)좌표가 음수인 점에서만 \(x\)축과 만난다.<div class="fig"><img src="fig_15.svg" style="width:150pt"></div>\(\displaystyle\int_{-1}^{1}f'(x)\,dx&gt;14\)일 때, &lt;보기&gt;에서 옳은 것만을 있는 대로 고른 것은?""",
          bogi=[('ㄱ', r"방정식 \(f(x)-f'(0)x=0\)의 서로 다른 실근의 개수는 \(2\)이다."),
                ('ㄴ', r"방정식 \(f(x)=0\)은 음이 아닌 실근을 갖지 않는다."),
                ('ㄷ', r"\(a&gt;4\)")],
          choices=['T:ㄱ', 'T:ㄱ, ㄴ', 'T:ㄱ, ㄷ', 'T:ㄴ, ㄷ', 'T:ㄱ, ㄴ, ㄷ'],
          ans=4,
          key='M60', src='2019학년도 수능 6월 모의평가 21번 · 10회 12번 숫자 변경',
          wrongs=['T:ㄱ, ㄴ, ㄷ', 'T:ㄱ, ㄷ'],
          level='중',
          sol=r"\(f'(x)=3x^2+2ax+b\)이다. \(f'(x)=0\)이 실근을 갖고 그 실근이 모두 음수이므로 판별식에서 \(a^2-3b\ge0\), 근과 계수의 관계에서 (두 근의 합) \(=-\dfrac{2a}3&lt;0\), (두 근의 곱) \(=\dfrac b3&gt;0\), 즉 \(a&gt;0\), \(b&gt;0\)이다.<br>\(\displaystyle\int_{-1}^{1}f'(x)\,dx=f(1)-f(-1)=(a+b+3)-(a-b+1)=2b+2&gt;14\)이므로 \(b&gt;6\)<br>ㄱ. \(f'(0)=b\)이므로 \(f(x)-f'(0)x=x^3+ax^2+2\)이다. \(h(x)=x^3+ax^2+2\)라 하면 \(h'(x)=x(3x+2a)\)이고 \(a&gt;0\)이므로 극댓값은 \(h\left(-\dfrac{2a}3\right)=\dfrac{4a^3}{27}+2&gt;0\), 극솟값은 \(h(0)=2&gt;0\)이다. 따라서 방정식 \(h(x)=0\)의 서로 다른 실근은 \(1\)개이다. (거짓)<br>ㄴ. \(a&gt;0\), \(b&gt;0\)이므로 \(x\ge0\)이면 \(f(x)=x^3+ax^2+bx+2\ge2&gt;0\)이다. 따라서 방정식 \(f(x)=0\)은 음이 아닌 실근을 갖지 않는다. (참)<br>ㄷ. \(a^2\ge3b&gt;18&gt;16\)이고 \(a&gt;0\)이므로 \(a&gt;4\) (참)<br>따라서 옳은 것은 ㄴ, ㄷ",
          fast=r"그림·조건 → \(a&gt;0\), \(b&gt;6\), \(a^2\ge3b\). \(f(x)-bx=x^3+ax^2+2\)는 극값이 모두 양수(극솟값 \(2\))라 실근 \(1\)개 (ㄱ 거짓). 계수가 모두 양수라 \(x\ge0\)에서 \(f&gt;0\) (ㄴ 참). \(a^2&gt;18\) → \(a&gt;4\) (ㄷ 참).",
          wrong=r"⑤ ㄱ, ㄴ, ㄷ: 원문처럼 \(f(x)-f'(0)x=x^2(x+a)\)로 보아 실근 \(0\), \(-a\)의 \(2\)개로 판정(10회에서 고른 ⑤와 같은 실수) · ③ ㄱ, ㄷ: 상수항 \(2\)를 놓쳐 \(x=0\)이 근이라 보고 ㄴ을 거짓, ㄱ을 참으로 판정",
          note=r"10회 12번(M60 변형)에서 수치만 바꿈: 상수항 \(1\) → \(2\), 정적분 조건 \(&gt;8\) → \(&gt;14\)(\(b&gt;3\) → \(b&gt;6\)), \(a&gt;3\) → \(a&gt;4\)(\(a^2&gt;18\)에서 참). 답이 ㄴ, ㄷ(④)이 되도록 보기 순서를 바꿔 실근 개수 문장을 ㄱ, \(a\)의 범위를 ㄷ에 둠(문장·선지 꼴은 그대로). 원문 함정 '\(x^2(x+a)\)로 보아 실근 \(2\)개'를 따르면 원래처럼 ⑤를 고르게 됨. 그림은 원래 그림(아래로 볼록, \(x\)축과 만나는 두 점의 \(x\)좌표가 모두 음수, 수치 없음)이 새 수치(예: \(a=6\), \(b=7\))에서도 같은 모양이라 원래 그림 파일(fig_15.svg, 이 폴더에 복사되어 있음)을 그대로 씀."),
  8: dict(body=r"""상수항이 \(0\)인 삼차함수 \(f(x)\)에 대하여 \(\displaystyle\int_{3p}^{3p+3}|f(x)|\,dx\ne\left|\int_{3p}^{3p+3}f(x)\,dx\right|\)가 되도록 하는 모든 실수 \(p\)의 값의 범위는 \(1&lt;p&lt;2\)이고, \(\displaystyle\int_0^6|f(x)+q|\,dx\ne\left|\int_0^6\{f(x)+q\}\,dx\right|\)가 되도록 하는 모든 실수 \(q\)의 값의 범위는 \(-64&lt;q&lt;0\)이다. \(f(3)\)의 값은?""",
          choices=['54', '59', '64', '69', '74'],
          ans=1,
          key='I75', src='2027학년도 수능 6월 모의평가 15번 · 10회 15번 숫자 변경',
          wrongs=['64'],
          level='상',
          sol=r"\(\displaystyle\int_a^b|h(x)|\,dx\ne\left|\int_a^b h(x)\,dx\right|\)는 열린구간 \((a,\,b)\)에서 \(h(x)\)의 부호가 바뀔 때 성립한다.<br>\(f(x)\)의 부호가 \(x=r\)에서 바뀌면 \(3p&lt;r&lt;3p+3\), 즉 \(\dfrac{r-3}3&lt;p&lt;\dfrac r3\)일 때 첫 번째 부등식이 성립한다. 그 범위들을 모은 것이 \(1&lt;p&lt;2\) 하나뿐이므로 부호가 바뀌는 점은 \(x=6\)뿐이다.<br>\(f(0)=0\)인데 \(x=0\)에서 부호가 바뀌지 않으므로 \(x=0\)은 중근이고 \(f(x)=cx^2(x-6)\) (\(c\ne0\))이다.<br>두 번째 부등식은 열린구간 \((0,\,6)\)에서 \(f(x)+q\)의 부호가 바뀔 때 성립하므로 \(-q\)가 이 구간에서 \(f(x)\)가 갖는 값(양 끝값 제외) 사이에 있어야 한다. \(q\)의 범위가 음수이므로 \(c&lt;0\)이고, \(f'(x)=3cx(x-4)\)에서 \([0,\,6]\)에서 \(f(x)\)의 최댓값은 \(f(4)=-32c\), 최솟값은 \(0\)이다. 따라서 \(0&lt;-q&lt;-32c\), 곧 \(32c&lt;q&lt;0\)이고 \(32c=-64\), \(c=-2\)이다.<br>\(f(x)=-2x^2(x-6)\)이므로 \(f(3)=-2\times9\times(-3)=54\)이다.",
          fast=r"창 \((3p,3p+3)\)이 부호 변화점 \(r\)을 품는 \(p\): \(\tfrac{r-3}3&lt;p&lt;\tfrac r3\) → \(r=6\), \(0\)은 중근: \(f=cx^2(x-6)\). \(q&lt;0\)이라 \(c&lt;0\), \([0,6]\) 최댓값 \(f(4)=-32c=64\) → \(c=-2\). \(f(3)=54\).",
          wrong=r"③ \(64\): \([0,\,6]\)에서 \(f(x)\)의 최댓값이 구간 가운데 \(x=3\)에서 나온다고 보아 \(f(3)=64\)로 둔 값(최댓값은 \(f(4)\), 10회 원래 문항의 오답 \(-32\)와 같은 실수)",
          note=r"10회 15번(I75 변형)에서 수치만 바꿈: 창 \([2p,\,2p+4]\), \(1&lt;p&lt;3\) → \([3p,\,3p+3]\), \(1&lt;p&lt;2\)(부호 변화점 \(x=6\)은 그대로), \(q\)의 범위 \(0&lt;q&lt;32\) → \(-64&lt;q&lt;0\)(최고차항의 계수의 부호가 음수로 바뀌어 최솟값 대신 최댓값 \(f(4)\)), 묻는 값 \(f(3)\)은 그대로. 창의 폭 \(3\)이 근 간격 \(6\)보다 작아 \(x=0\)이 단순근이면 \(-1&lt;p&lt;0\)이 더 생기므로 '\(0\)은 중근' 판단이 그대로 살아 있음. 선지 공차 \(5\) 오름차순, 극값을 구간 가운데로 착각한 값 \(64\)."),
  9: dict(body=r"""최고차항의 계수가 \(1\)인 삼차함수 \(f(x)\)가 다음 조건을 만족시킬 때, 정수 \(k\)에 대하여 곡선 \(y=f(x)\)와 직선 \(y=(x-k+4)f'(k)\)가 서로 다른 세 점에서 만나도록 하는 \(k\)의 개수는?""",
          cond=[('가', r"모든 실수 \(x\)에 대하여 부등식 \((x-18)f(x)\ge0\)이 성립한다."),
                ('나', r"\(f(0)=0\)")],
          choices=['17', '16', '15', '14', '13'],
          ans=5,
          key='M32', src='2024년 수능특강 [24009-0123] · 10회 17번 숫자 변경',
          wrongs=['16', '17'],
          level='상',
          sol=r"(가)에서 \(x&lt;18\)이면 \(f(x)\le0\), \(x&gt;18\)이면 \(f(x)\ge0\)이므로 \(f(18)=0\)이고, (나)에서 \(f(0)=0\)인데 \(x=0\)의 좌우에서 \(f(x)\)의 부호가 바뀌지 않으므로 \(f(x)=x^2(x-18)\), \(f'(x)=3x^2-36x\)이다.<br>\(h(x)=f(x)-(x-k+4)f'(k)\)라 하면 \(h'(x)=f'(x)-f'(k)=3(x^2-k^2)-36(x-k)=3(x-k)(x+k-12)\)이다.<br>(i) \(k=6\)이면 \(h'(x)=3(x-6)^2\ge0\)이므로 \(h(x)\)는 증가하고 실근은 \(1\)개이다.<br>(ii) \(k\ne6\)이면 \(h(x)\)는 \(x=k,\ x=12-k\)에서 극값을 갖는다.<br>\(h(k)=k^3-18k^2-4(3k^2-36k)=k^3-30k^2+144k=k(k-6)(k-24)\)<br>\(f'(12-k)=f'(k)\)이므로 \(h(12-k)=f(12-k)-(16-2k)f'(k)=-(k-12)^2(k+6)-6k(8-k)(k-12)=(k-12)(5k^2-42k+72)=(k-12)(k-6)(5k-12)\)<br>곡선과 직선이 서로 다른 세 점에서 만나려면 방정식 \(h(x)=0\)의 서로 다른 실근이 \(3\)개이어야 하고, 이를 위해서는 (극댓값)\(\times\)(극솟값)\(&lt;0\)이어야 하므로<br>\(h(k)h(12-k)=(k-6)^2\,k(k-24)(k-12)(5k-12)&lt;0\)<br>\(k\ne6\)에서 \((k-6)^2&gt;0\)이므로 \(k(5k-12)(k-12)(k-24)&lt;0\), 곧 \(0&lt;k&lt;\dfrac{12}5\) 또는 \(12&lt;k&lt;24\)이다. \(k=0,\ \dfrac{12}5,\ 12,\ 24\)이면 극값 하나가 \(0\)이어서 실근이 \(2\)개이다.<br>따라서 정수 \(k\)는 \(1,\ 2,\ 13,\ 14,\ \cdots,\ 23\)이고 그 개수는 \(13\)이다.",
          fast=r"\(f=x^2(x-18)\). \(h(x)=f(x)-(x-k+4)f'(k)\), \(h'=3(x-k)(x+k-12)\) → 극점 \(k,\ 12-k\)(\(k=6\)이면 증가함수, 실근 \(1\)개). \(h(k)=k(k-6)(k-24)\), \(h(12-k)=(k-12)(k-6)(5k-12)\). 곱 \((k-6)^2k(k-24)(k-12)(5k-12)&lt;0\) → \(0&lt;k&lt;\dfrac{12}5\) 또는 \(12&lt;k&lt;24\) → 정수 \(1,\ 2,\ 13,\ \cdots,\ 23\), \(13\)개.",
          wrong=r"② \(16\): 실근이 \(2\)개인 끝점 \(k=0,\ 12,\ 24\)까지 세어 '서로 다른 실근이 \(2\)개 이상'인 정수 \(k\)를 센 값 / ① \(17\): 극값의 곱을 \(\le0\)으로 풀어 곱이 \(0\)이 되는 \(k=0,\ 6,\ 12,\ 24\)를 모두 넣은 값(\(k=6\)은 두 극점이 겹쳐 직선이 변곡점에서의 접선이 되므로 실근이 \(1\)개)",
          note=r"10회 17번(M32 변형)에서 수치만 바꿈: (가)의 \(9\) → \(18\), 직선 \(y=(x-k+2)f'(k)\) → \(y=(x-k+4)f'(k)\)(\(k=6\)에서 직선이 변곡점에서의 접선이 되도록 두 수를 함께 \(2\)배로 바꿔 극값의 곱에 \((k-6)^2\)이 남는 설계 그대로). 갈래 구조(\(h'=f'(x)-f'(k)\)의 두 근 \(k,\ 12-k\) → 극값의 곱의 부호로 범위 \(0&lt;k&lt;\dfrac{12}5\), \(12&lt;k&lt;24\) → \(k=6\)은 실근 \(1\)개, 끝점 \(0,\ \dfrac{12}5,\ 12,\ 24\)는 접함) 그대로. 두 오답(끝점 포함 \(16\), 곱 \(\le0\)으로 \(k=6\)까지 넣은 \(17\))이 모두 정답보다 커서 선지를 공차 \(1\) 내림차순으로 두어 정답이 ⑤에 옴(끝점 포함 값이 원래 학생이 고른 자리 ②)."),
  10: dict(body=r"""최고차항의 계수가 \(1\)인 사차함수 \(f(x)\)가 다음 조건을 만족시킬 때, \(f(1)\)의 값은?""",
          cond=[('가', r"실수 \(t\)에 대하여 함수 \(|f(x)-f(t)|\)가 미분가능하지 않은 실수 \(x\)의 개수를 \(h(t)\)라 할 때, \(h(t)=1\)을 만족시키는 모든 실수 \(t\)의 값의 합은 \(\dfrac12\)이다."),
                ('나', r"곡선 \(y=f(x)\) 위의 점 \((0,\ f(0))\)에서의 접선의 기울기는 \(0\)이고, \(f(-1)=3\)이다."),
                ('다', r"모든 실수 \(x\)에 대하여 부등식 \(f(x)&gt;0\)이 성립한다.")],
          choices=['-1', '2', '5', '8', '11'],
          ans=2,
          key='M34', src='2024년 수능특강 [24009-0127] · 10회 18번 숫자 변경',
          wrongs=['-1', '5'],
          level='최상',
          sol=r"\(|f(x)-f(t)|\)는 \(f(x)-f(t)\)의 인수 \(x-a\)가 한 번만 곱해진 근 \(x=a\)에서만 미분가능하지 않고, 두 번 이상 곱해진 근에서는 미분가능하다. 사차식 \(f(x)-f(t)\)에서 한 번만 곱해진 실근이 하나뿐이면 남은 인수가 \((x-p)^3\) 꼴이어야 하므로 \(h(t)=1\)이면 \(f(x)-f(t)=(x-p)^3(x-q)\) \((p\ne q)\)이다. 이때 \(f\)는 \(x=p\)에서 접선의 기울기가 \(0\)이고 극값을 갖지 않으며, \(h(t)=1\)을 만족시키는 \(t\)는 \(f(t)=f(p)\)인 \(t=p,\ q\)이다. 따라서 \(p+q=\dfrac12\)이고, \(c=f(p)\)라 하면 \(f(x)=(x-p)^3(x-q)+c\)이다.<br>\(f'(x)=(x-p)^2(4x-3q-p)\)이고 (나)에서 \(f'(0)=0\)이므로 \(p=0\) 또는 \(3q+p=0\)이다.<br>(i) \(p=0\), \(q=\dfrac12\)일 때: \(f(x)=x^3\left(x-\dfrac12\right)+c\), \(f(-1)=\dfrac32+c=3\)에서 \(c=\dfrac32\)이다. \(f'(x)=x^2\left(4x-\dfrac32\right)\)이므로 \(f\)의 최솟값은 \(f\left(\dfrac38\right)=\dfrac32-\dfrac{27}{4096}&gt;0\)이고 (다)를 만족시킨다.<br>(ii) \(3q+p=0\), \(p+q=\dfrac12\)일 때: \(p=\dfrac34\), \(q=-\dfrac14\)이고 \(f(x)=\left(x-\dfrac34\right)^3\left(x+\dfrac14\right)+c\), \(f(-1)=\dfrac{1029}{256}+c=3\)에서 \(c=-\dfrac{261}{256}\)이다. \(f\)는 \(x=0\)에서 극소이고 최솟값 \(f(0)=-\dfrac{27}{256}-\dfrac{261}{256}=-\dfrac98&lt;0\)이므로 (다)를 만족시키지 않는다.<br>따라서 \(f(x)=x^3\left(x-\dfrac12\right)+\dfrac32\)이고 \(f(1)=\dfrac12+\dfrac32=2\)",
          fast=r"\(h(t)=1\) ⇔ \(f(t)\)가 정류 변곡점의 높이: \(f-f(p)=(x-p)^3(x-q)\), \(p+q=\frac12\). \(f'=(x-p)^2(4x-3q-p)\), \(f'(0)=0\) → \(p=0\) 또는 \((p,q)=\left(\frac34,-\frac14\right)\). \(p=0\): \(c=3-\frac32=\frac32\), 최솟값 \(\frac32-\frac{27}{4096}&gt;0\) ✓. \(p=\frac34\): \(c=3-\frac{1029}{256}\), 최솟값 \(f(0)=-\frac98&lt;0\) ✗. \(f(1)=\frac12+\frac32=2\).",
          wrong=r"① \(-1\): \(f'(0)=0\)을 극소점으로만 보아 (ii)만 세우고 (다)를 확인하지 않은 값. (ii)의 함수에서 \(f(1)=\frac5{256}-\frac{261}{256}=-1\)이지만 최솟값이 \(-\frac98\)이라 (다)와 어긋난다. 원문 습관대로 \(x=1\)을 삼중근으로 두어 \(f(x)=(x-1)^3\left(x+\frac12\right)+c\)로 세워도 \(c=-1\), \(f(1)=-1\)이 나온다(이 함수는 \(f'(0)\ne0\)) / ③ \(5\): (i)에서 \(f(-1)=(-1)^3\left(-1-\frac12\right)+c\)의 부호를 틀려 \(-\frac32+c=3\), \(c=\frac92\)로 두고 구한 값",
          note=r"10회 18번(M34 변형)에서 수치만 바꿈: (가)의 합 \(1\) → \(\dfrac12\), (나)의 \(f(-1)=5\) → \(f(-1)=3\)(\(f'(0)=0\)과 (다), 묻는 값 \(f(1)\)은 그대로). 갈래 구조(\(f'(0)=0\)이 정류 변곡점 \(p=0\)인지 극소점 \(3q+p=0\)인지 두 갈래 → 갈래마다 \(f(-1)=3\)으로 상수 \(c\)를 정함(\(\dfrac32\), \(-\dfrac{261}{256}\)) → (다)가 극솟값의 부호로 극소점 갈래를 지움) 그대로. 버려지는 갈래의 값 \(-1\)(원문 습관 \((x-1)^3\)으로 세운 값과도 같음)이 ①, 정답 ②. 10회에서 고른 ② \(0\)(\(x=1\)이 근이라 \(f(1)=0\))은 합이 \(\dfrac12\)이 되어 \(q=\dfrac12\ne1\)이라 이 문항에선 생기지 않으므로 상수 계산의 부호 실수 \(5\)를 두 번째 오답으로 둠. 선지 공차 \(3\) 오름차순."),
}
